using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text.Json;
using QuantLOL.Core;
using Xunit;

namespace QuantLOL.Tests
{
    /// <summary>
    /// Cross-language parity between the Python research engine (research/quantlol_ref.py) and the
    /// shipped C# core. The fixture is generated by research/make_parity.py from a committed slice of
    /// the 5-minute research data; every expected value comes from the Python side.
    ///
    /// A failure here means the backtest and the bot no longer implement the same rules. Fix the
    /// disagreement - do not loosen the tolerance.
    /// </summary>
    public class ParityTests
    {
        static readonly JsonDocument Doc = JsonDocument.Parse(File.ReadAllText(FixturePath()));
        static readonly JsonElement Root = Doc.RootElement;

        static string FixturePath()
        {
            var dir = AppContext.BaseDirectory;
            for (int i = 0; i < 6 && dir != null; i++)
            {
                var p = Path.Combine(dir, "fixtures", "parity.json");
                if (File.Exists(p)) return p;
                dir = Path.GetDirectoryName(dir);
            }
            throw new FileNotFoundException("fixtures/parity.json not found next to the test assembly");
        }

        static double D(JsonElement e, string name) => e.GetProperty(name).GetDouble();
        static double D(JsonElement e, string name, double fallback)
            => e.TryGetProperty(name, out var v) && v.ValueKind == JsonValueKind.Number ? v.GetDouble() : fallback;
        static int I(JsonElement e, string name) => (int)e.GetProperty(name).GetInt32();
        static bool B(JsonElement e, string name, bool fallback = false)
            => e.TryGetProperty(name, out var v) && (v.ValueKind == JsonValueKind.True || v.ValueKind == JsonValueKind.False)
                ? v.GetBoolean() : fallback;

        static BarDto[] Bars()
        {
            var list = new List<BarDto>();
            foreach (var row in Root.GetProperty("bars").EnumerateArray())
            {
                var p = new List<JsonElement>(row.EnumerateArray());
                var t = DateTime.ParseExact(p[0].GetString(), "yyyy-MM-dd HH:mm:ss",
                                            CultureInfo.InvariantCulture, DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal);
                list.Add(new BarDto(t, p[1].GetDouble(), p[2].GetDouble(), p[3].GetDouble(),
                                    p[4].GetDouble(), p[5].GetDouble()));
            }
            return list.ToArray();
        }

        static StructureOptions Options()
        {
            var m = Root.GetProperty("meta").GetProperty("structure_options");
            return new StructureOptions
            {
                SwingLookback = I(m, "swing_lookback"),
                ScanBars = I(m, "scan_bars"),
                TickSize = D(m, "tick"),
                MinSweepPierceTicks = I(m, "min_sweep_pierce_ticks"),
                MinFvgTicks = I(m, "min_fvg_ticks"),
                ObLookbackBars = I(m, "ob_lookback"),
                SweepWindowBars = I(m, "sweep_window"),
                DealingRangeSwings = I(m, "dealing_swings"),
                FvgScanBars = I(m, "fvg_scan"),
            };
        }

        // ------------------------------------------------------------------ structure
        [Fact]
        public void StructureMatchesReferenceEngine()
        {
            var bars = Bars();
            var c = Root.GetProperty("structure");
            var exp = c.GetProperty("expected");
            var s = StructureAnalyzer.Analyze(bars, I(c, "last_index"), Options());

            Assert.Equal(I(exp, "bars_analysed"), s.BarsAnalysed);
            AssertEx.Near(D(exp, "atr"), s.Atr, 1e-6, "ATR");
            Assert.Equal(I(exp, "trend"), s.Trend);
            Assert.Equal(I(exp, "swings"), s.Swings.Count);
            Assert.Equal(I(exp, "last_bos_i"), s.LastBosIndex);
            Assert.Equal(I(exp, "last_bos_dir"), s.LastBosDirection);
            AssertEx.Near(D(exp, "last_bos_level"), s.LastBosLevel, 1e-6, "last BOS level");
            Assert.Equal(I(exp, "last_choch_i"), s.LastChochIndex);
            Assert.Equal(I(exp, "last_choch_dir"), s.LastChochDirection);
            AssertEx.Near(D(exp, "last_choch_level"), s.LastChochLevel, 1e-6, "last CHoCH level");
            AssertEx.Near(D(exp, "dealing_high"), s.DealingHigh, 1e-6, "dealing high");
            AssertEx.Near(D(exp, "dealing_low"), s.DealingLow, 1e-6, "dealing low");

            CompareSweep(exp.GetProperty("bull_sweep"), s.BullishSweep, "bullish sweep");
            CompareSweep(exp.GetProperty("bear_sweep"), s.BearishSweep, "bearish sweep");
            CompareFvg(exp.GetProperty("bull_fvg"), s.LastBullishFvg, "bullish FVG");
            CompareFvg(exp.GetProperty("bear_fvg"), s.LastBearishFvg, "bearish FVG");
            CompareZone(exp.GetProperty("bull_ob"), s.BullishOrderBlock, "bullish order block");
            CompareZone(exp.GetProperty("bear_ob"), s.BearishOrderBlock, "bearish order block");
        }

        static void CompareSweep(JsonElement e, SweepEvent s, string label)
        {
            if (e.ValueKind == JsonValueKind.Null) { Assert.Null(s); return; }
            Assert.NotNull(s);
            Assert.Equal(I(e, "i"), s.BarIndex);
            Assert.Equal(I(e, "dir"), s.Direction);
            Assert.Equal(Enum.Parse<LevelKind>(e.GetProperty("kind").GetString()), s.LevelKind);
            AssertEx.Near(D(e, "level"), s.LevelPrice, 1e-6, label + " level");
            AssertEx.Near(D(e, "extreme"), s.Extreme, 1e-6, label + " extreme");
            AssertEx.Near(D(e, "pierce_ticks"), s.PierceTicks, 1e-6, label + " pierce");
        }

        static void CompareFvg(JsonElement e, FvgZone f, string label)
        {
            if (e.ValueKind == JsonValueKind.Null) { Assert.Null(f); return; }
            Assert.NotNull(f);
            Assert.Equal(I(e, "i"), f.BarIndex);
            AssertEx.Near(D(e, "top"), f.Top, 1e-6, label + " top");
            AssertEx.Near(D(e, "bottom"), f.Bottom, 1e-6, label + " bottom");
        }

        static void CompareZone(JsonElement e, Zone z, string label)
        {
            if (e.ValueKind == JsonValueKind.Null) { Assert.False(z.IsValid, label + " should be absent"); return; }
            Assert.True(z.IsValid, label + " should exist");
            AssertEx.Near(D(e, "top"), z.Top, 1e-6, label + " top");
            AssertEx.Near(D(e, "bottom"), z.Bottom, 1e-6, label + " bottom");
        }

        // -------------------------------------------------------------------- profile
        [Fact]
        public void MarketProfileMatchesReferenceEngine()
        {
            var bars = Bars();
            var c = Root.GetProperty("profile");
            var exp = c.GetProperty("expected");
            var p = MarketProfileBuilder.Build(bars, I(c, "start"), I(c, "end"), D(c, "bin"),
                                               D(c, "va_percent"), I(c, "ib_bars"));
            Assert.True(p.HasData, "profile should have data");
            AssertEx.Near(D(exp, "poc"), p.Poc, 1e-6, "POC");
            AssertEx.Near(D(exp, "vah"), p.Vah, 1e-6, "VAH");
            AssertEx.Near(D(exp, "val"), p.Val, 1e-6, "VAL");
            AssertEx.Near(D(exp, "high"), p.SessionHigh, 1e-6, "session high");
            AssertEx.Near(D(exp, "low"), p.SessionLow, 1e-6, "session low");
            AssertEx.Near(D(exp, "total_volume"), p.TotalVolume, 1e-6, "total volume");
            AssertEx.Near(D(exp, "ib_high"), p.InitialBalanceHigh, 1e-6, "initial balance high");
            AssertEx.Near(D(exp, "ib_low"), p.InitialBalanceLow, 1e-6, "initial balance low");
            Assert.Equal(B(exp, "partial"), p.Partial);
        }

        // ------------------------------------------------------------------ order flow
        [Fact]
        public void OrderFlowMatchesReferenceEngine()
        {
            var bars = Bars();
            var c = Root.GetProperty("orderflow");
            var exp = c.GetProperty("expected");
            int last = I(c, "last_index"), window = I(c, "window");
            var of = OrderFlowAnalyzer.Compute(bars, last, window, D(c, "avg_volume"));
            Assert.Equal(window, of.BarsUsed);
            AssertEx.Near(D(exp, "delta"), of.Delta, 1e-6, "delta");
            AssertEx.Near(D(exp, "ratio"), of.DeltaRatio, 1e-9, "delta ratio");
            AssertEx.Near(D(exp, "buy"), of.BuyVolume, 1e-6, "buy volume");
            AssertEx.Near(D(exp, "sell"), of.SellVolume, 1e-6, "sell volume");
            AssertEx.Near(D(exp, "total"), of.TotalVolume, 1e-6, "total volume");
            Assert.Equal(B(exp, "div_bull"), of.BullishDivergence);
            Assert.Equal(B(exp, "div_bear"), of.BearishDivergence);
        }

        // ------------------------------------------------------------------------ risk
        [Fact]
        public void RiskMathMatchesReferenceEngine()
        {
            foreach (var c in Root.GetProperty("risk").EnumerateArray())
            {
                var n = RiskMath.Compute(D(c, "entry"), D(c, "stop"), D(c, "target"),
                                         D(c, "money"), D(c, "commission"), D(c, "slippage"));
                var e = c.GetProperty("expected");
                AssertEx.Near(D(e, "dist"), n.StopDistance, 1e-9, "stop distance");
                AssertEx.Near(D(e, "risk"), n.RiskUsd, 1e-9, "risk USD");
                AssertEx.Near(D(e, "net_reward"), n.NetRewardUsd, 1e-9, "net reward");
                AssertEx.Near(D(e, "rr_net"), n.RrNet, 1e-9, "net R:R");
                AssertEx.Near(D(e, "rr_gross"), n.RrGross, 1e-9, "gross R:R");
            }
        }

        [Fact]
        public void DrawdownGuardMatchesReferenceEngine()
        {
            var c = Root.GetProperty("guard");
            var g = new DrawdownGuard(D(c, "reference"), D(c, "daily_loss"), D(c, "equity_dd"));
            var t0 = new DateTime(2026, 3, 2, 14, 0, 0, DateTimeKind.Utc);
            int k = 0;
            foreach (var ev in c.GetProperty("events").EnumerateArray())
            {
                var t = t0.AddMinutes(5 * k++);
                g.OnTradeClosed(D(ev, "pnl"), t, D(ev, "equity"));
                var st = g.Evaluate(D(ev, "equity"), t);
                Assert.Equal(B(ev, "allowed"), st.Allowed);
            }
            var exp = c.GetProperty("expected");
            Assert.Equal(B(exp, "latched"), g.KillSwitchLatched);
            AssertEx.Near(D(exp, "realized_today"), g.DailyRealizedPnl, 1e-9, "realised today");
        }

        // ------------------------------------------------------------------- decisions
        [Fact]
        public void SignalDecisionsMatchReferenceEngine()
        {
            var bars = Bars();
            int n = 0;
            foreach (var c in Root.GetProperty("decisions").EnumerateArray())
            {
                var x = Inputs(bars, c);
                var d = SignalEngine.Evaluate(x);
                var e = c.GetProperty("expected");
                string name = c.GetProperty("name").GetString();
                string state = e.GetProperty("state").GetString();
                string reject = e.GetProperty("reject").GetString();

                Assert.True(state == "bull" ? d.State == SignalState.Bullish
                          : state == "bear" ? d.State == SignalState.Bearish
                          : state == "unavailable" ? d.State == SignalState.Unavailable
                          : d.State == SignalState.Neutral, name + ": state was " + d.State);
                Assert.Equal(reject, d.Reject.ToString());
                Assert.Equal(I(e, "dir"), d.Direction);
                if (state == "bull" || state == "bear")
                {
                    Assert.Equal((int)Math.Round(D(e, "score")), d.Score);
                    AssertEx.Near(D(e, "entry"), d.Entry, 1e-6, name + " entry");
                    AssertEx.Near(D(e, "stop"), d.Stop, 1e-6, name + " stop");
                    AssertEx.Near(D(e, "target"), d.Target, 1e-6, name + " target");
                    AssertEx.Near(D(e, "risk_usd"), d.RiskUsd, 1e-6, name + " risk");
                    AssertEx.Near(D(e, "rr_net"), d.RrNet, 1e-6, name + " net R:R");
                    Assert.Equal(B(e, "synthetic"), d.TargetIsSynthetic);
                    Assert.Equal(e.GetProperty("setup").GetString(), d.SetupType);
                }
                n++;
            }
            Assert.True(n >= 8, "expected a meaningful number of parity decisions, got " + n);
        }

        static SignalInputs Inputs(BarDto[] bars, JsonElement c)
        {
            var cfg = c.GetProperty("config");
            var s = c.GetProperty("snapshot");
            int index = I(c, "bar_index");
            double tick = D(cfg, "tick");
            double price = bars[index].Close;

            var x = new SignalInputs
            {
                EntryBars = bars,
                LastClosedIndex = index,
                EntryPrice = price,
                TickSize = tick,
                Bid = price,
                Ask = price + D(cfg, "spread_ticks") * tick,
                SpreadKnown = true,
                MaxSpreadTicks = (int)D(cfg, "max_spread_ticks"),
                MoneyPerPriceUnit = D(cfg, "money_per_price"),
                CommissionRoundTripUsd = D(cfg, "commission"),
                SlippageRoundTripUsd = D(cfg, "slippage"),
                Caps = new RiskCaps
                {
                    MaxRiskPerTradeUsd = D(cfg, "max_risk"),
                    MinRewardRisk = D(cfg, "min_rr"),
                    EnforceRiskCap = true,
                },
                MinScore = D(cfg, "min_score"),
                RequireLocation = B(cfg, "require_location"),
                RequireOrderFlow = B(cfg, "require_order_flow"),
                RequireConfirmation = B(cfg, "require_confirmation"),
                EnableFvg = B(cfg, "enable_fvg"),
                EnableOrderBlock = B(cfg, "enable_order_block"),
                EnableGex = false,
                EnableVix = B(cfg, "enable_vix"),
                BlockOnHighVix = B(cfg, "block_on_high_vix"),
                VixHighThreshold = D(cfg, "vix_high"),
                AllowSyntheticTarget = B(cfg, "allow_synthetic"),
                FallbackRr = D(cfg, "fallback_rr"),
                StopBufferTicks = D(cfg, "stop_buffer_ticks"),
                SweepWindowBars = I(cfg, "sweep_window"),
                ConfirmWindowBars = I(cfg, "confirm_window"),
                LocationProximityTicks = D(cfg, "location_proximity_ticks"),
                EntryStructure = Snapshot(s),
            };

            var prof = c.GetProperty("profile");
            if (prof.ValueKind != JsonValueKind.Null)
            {
                x.SessionProfile = new ProfileSnapshot
                {
                    HasData = true,
                    Poc = D(prof, "poc"),
                    Vah = D(prof, "vah"),
                    Val = D(prof, "val"),
                    SessionHigh = D(prof, "high"),
                    SessionLow = D(prof, "low"),
                    TotalVolume = D(prof, "total_volume"),
                };
            }

            var of = c.GetProperty("order_flow");
            if (of.ValueKind != JsonValueKind.Null)
            {
                x.OrderFlowEnabled = true;
                x.OrderFlow = new OrderFlowSnapshot
                {
                    BarsUsed = I(of, "n"),
                    DeltaRatio = D(of, "ratio"),
                    BullishDivergence = B(of, "div_bull"),
                    BearishDivergence = B(of, "div_bear"),
                };
            }

            var targets = new List<LevelRef>();
            foreach (var t in c.GetProperty("targets").EnumerateArray())
                targets.Add(new LevelRef(t.GetDouble(), LevelKind.SwingHigh));
            x.Targets = targets.ToArray();

            var vix = c.GetProperty("vix");
            if (vix.ValueKind != JsonValueKind.Null)
            {
                x.Vix = new VixSnapshot
                {
                    Valid = B(vix, "valid"),
                    Level = D(vix, "level"),
                    AsOfUtc = new DateTime(2026, 3, 2, 20, 0, 0, DateTimeKind.Utc),
                };
            }
            return x;
        }

        static StructureSnapshot Snapshot(JsonElement s)
        {
            var st = new StructureSnapshot
            {
                LastChochIndex = I(s, "last_choch_i"),
                LastChochDirection = I(s, "last_choch_dir"),
                LastChochLevel = D(s, "last_choch_level"),
                DealingHigh = D(s, "dealing_high"),
                DealingLow = D(s, "dealing_low"),
                Atr = D(s, "atr"),
            };
            st.BullishSweep = Sweep(s.GetProperty("bull_sweep"));
            st.BearishSweep = Sweep(s.GetProperty("bear_sweep"));
            st.LastBullishFvg = Fvg(s.GetProperty("bull_fvg"));
            st.LastBearishFvg = Fvg(s.GetProperty("bear_fvg"));
            st.BullishOrderBlock = ZoneOf(s.GetProperty("bull_ob"));
            st.BearishOrderBlock = ZoneOf(s.GetProperty("bear_ob"));
            return st;
        }

        static SweepEvent Sweep(JsonElement e)
        {
            if (e.ValueKind == JsonValueKind.Null) return null;
            return new SweepEvent
            {
                BarIndex = I(e, "i"),
                Direction = I(e, "dir"),
                LevelKind = Enum.Parse<LevelKind>(e.GetProperty("kind").GetString()),
                LevelPrice = D(e, "level"),
                Extreme = D(e, "extreme"),
                PierceTicks = D(e, "pierce_ticks"),
            };
        }

        static FvgZone Fvg(JsonElement e)
        {
            if (e.ValueKind == JsonValueKind.Null) return null;
            return new FvgZone
            {
                BarIndex = I(e, "i"),
                Top = D(e, "top"),
                Bottom = D(e, "bottom"),
                Filled = B(e, "filled"),
                Direction = D(e, "top") >= D(e, "bottom") ? 1 : -1,
            };
        }

        static Zone ZoneOf(JsonElement e)
        {
            if (e.ValueKind == JsonValueKind.Null) return new Zone();
            return new Zone { Top = D(e, "top"), Bottom = D(e, "bottom"), BarIndex = 0 };
        }
    }
}
